package deps

import (
	"slices"
	"strings"
	"testing"

	"github.com/invowk/invowk/internal/discovery"
	"github.com/invowk/invowk/internal/testutil/alloygolden"
)

// scopeGoldenFile holds every instance of formal/alloy/ScopeConstruction.als's
// `golden` command at its declared scope, regenerated by
// `scripts/formal.py golden ScopeConstruction`.
const scopeGoldenFile = "testdata/formal/scope_construction_golden.json.gz"

func goldenSourceID(atom string) string {
	if strings.HasPrefix(atom, "RootSrc$") {
		return string(discovery.SourceIDInvowkfile)
	}
	return alloygolden.ID(atom)
}

// scopeCaseFromAlloy translates one Alloy instance into a scopeCase. Atoms map
// to valid identifiers: Mod$N -> io.example.modN, Src$N -> srcN,
// RootSrc -> "invowkfile", Key$N -> a Git URL. It also returns the model's
// allowedImpl decision for each command index.
func scopeCaseFromAlloy(inst alloygolden.Instance) (c scopeCase, allowed []bool) {
	callerAtom := inst.Atoms("Caller")[0] // a one sig; alloygolden.Load checks the file
	selfAtom := inst.Target("self", callerAtom)
	allowedAtoms := inst.Targets("allowedSet", callerAtom)

	index := make(map[string]int)
	for i, cmdAtom := range inst.Atoms("Cmd") {
		index[cmdAtom] = i
	}
	for _, cmdAtom := range inst.Atoms("Cmd") {
		cmd := scopeCmd{
			src:      goldenSourceID(inst.Target("src", cmdAtom)),
			global:   inst.In("GlobalCmd", cmdAtom),
			explicit: inst.In("Explicit", cmdAtom),
			parent:   -1,
		}
		if parentAtom := inst.Target("childOf", cmdAtom); parentAtom != "" {
			cmd.parent = index[parentAtom]
		}
		if modAtom := inst.Target("mod", cmdAtom); modAtom != "" {
			cmd.mod = alloygolden.ModuleID(modAtom)
		}
		if cmdAtom == selfAtom {
			c.self = len(c.cmds)
		}
		c.cmds = append(c.cmds, cmd)
		allowed = append(allowed, slices.Contains(allowedAtoms, cmdAtom))
	}
	for _, keyAtom := range inst.Targets("requires", callerAtom) {
		c.requires = append(c.requires, alloygolden.ID(keyAtom))
	}
	c.lock = make(map[string]scopeLockEntry)
	for _, tuple := range inst.Rel["lock"] {
		entryAtom := tuple[2]
		c.lock[alloygolden.ID(tuple[1])] = scopeLockEntry{
			mod: alloygolden.ModuleID(inst.Target("eid", entryAtom)),
			src: goldenSourceID(inst.Target("esrc", entryAtom)),
		}
	}
	return c, allowed
}

// TestScopeConstructionGoldenVectors replays every instance of the Alloy
// command-scope model against the real buildCommandScope and CanCallTarget:
// for each discovered command source, the real decision must equal the
// model's allowedImpl decision recorded in Caller.allowedSet.
func TestScopeConstructionGoldenVectors(t *testing.T) {
	t.Parallel()

	instances := alloygolden.Load(t, scopeGoldenFile, "ScopeConstruction")

	disagreements := 0
	report := func(format string, args ...any) {
		disagreements++
		if disagreements <= 5 {
			t.Errorf(format, args...)
		}
	}
	for i, inst := range instances {
		c, modelAllowed := scopeCaseFromAlloy(inst)
		// The Go transcriptions of discoveryFacts and intendedAllowed must
		// agree with Alloy on every instance, or the rapid test checks the
		// code against a drifted oracle.
		if violation := c.discoveryFactsViolation(); violation != "" {
			report("instance %d: Alloy instance violates the Go discovery facts: %s\n%+v", i, violation, c)
		}
		actual := c.realDecisions(t)
		for target := range c.cmds {
			if actual[target] != modelAllowed[target] {
				report("instance %d target %d: real decision allowed=%v, model allowedImpl=%v\n%+v", i, target, actual[target], modelAllowed[target], c)
			}
			if intended := c.intendedAllowed(target); intended != modelAllowed[target] {
				report("instance %d target %d: Go intendedAllowed=%v, model allowedImpl=%v\n%+v", i, target, intended, modelAllowed[target], c)
			}
		}
	}
	if disagreements > 0 {
		t.Fatalf("%d disagreements with ScopeConstruction over %d instances", disagreements, len(instances))
	}
}
